// Maps the pages' own frontmatter to what Docusaurus expects, as the pages are read
// (`markdown.parseFrontMatter` in docusaurus.config.ts), so the Markdown files keep their own
// field names.
//
// - `sidebar.order` / `sidebar.label` → `sidebar_position` / `sidebar_label` (the sidebars list
//   pages explicitly, so these only matter for autogenerated ones, but keep them equivalent).
// - `displayed_sidebar`: course overviews show the course list, lessons (hidden ones too) their
//   course's sidebar, labs the lab list (scripts/content.mjs, sidebarFor).
// - Lessons of a draft course (`draft: true` on its overview) are drafts too, so the whole course
//   is left out of production builds, as its overview and sidebar are (scripts/content.mjs).
// - Course overviews get no previous/next links: learners enter a course with its Start/Continue
//   button.
// - The default title is hidden (`hide_title`): src/theme/DocItem/Content renders it with the
//   course or lab picture beside it and the page dates underneath.
// - Docusaurus uses `image` as the page's link-preview picture, but most sites showing previews
//   (chat, social) can't show SVG. An SVG picture moves to `picture` (still shown on the page), so the
//   preview falls back to the site's card (themeConfig.image); PNG, JPEG and WebP pictures stay.
// Everything else is left as it is; the page fields are checked by scripts/schema.mjs.
import { existsSync } from 'node:fs';
import { join, relative } from 'node:path';
import { COURSES_DIR, courseSidebarId, DOCS_DIR, readFrontmatter, sidebarFor } from './content.mjs';

/** Whether a course's overview (docs/courses/<slug>/index.md) is marked `draft: true`. */
function isDraftCourse(slug) {
	const index = ['index.md', 'index.mdx'].map((f) => join(COURSES_DIR, slug, f)).find(existsSync);
	return index !== undefined && readFrontmatter(index).draft === true;
}

/** Whether a picture can be a link preview (SVG can't, on most sites). */
export const previewable = (image) => typeof image === 'string' && !/\.svg$/i.test(image);

export function toDocusaurus(frontMatter, filePath) {
	const rel = relative(DOCS_DIR, filePath);
	if (rel.startsWith('..')) return frontMatter;
	const fm = { ...frontMatter };
	if (fm.image !== undefined && !previewable(fm.image)) {
		fm.picture = fm.image;
		delete fm.image;
	}
	if (fm.sidebar?.order !== undefined && fm.sidebar_position === undefined) fm.sidebar_position = fm.sidebar.order;
	if (fm.sidebar?.label && fm.sidebar_label === undefined) fm.sidebar_label = fm.sidebar.label;
	fm.hide_title ??= true;
	const relPath = rel.split('\\').join('/');
	const sidebar = sidebarFor(relPath);
	if (sidebar && fm.displayed_sidebar === undefined) fm.displayed_sidebar = sidebar;
	// Lessons show their course's sidebar; `relPath` is courses/<slug>/….
	const slug = relPath.split('/')[1];
	if (sidebar === courseSidebarId(slug) && fm.draft === undefined && isDraftCourse(slug)) fm.draft = true;
	if (sidebar === 'courses') {
		fm.pagination_prev ??= null;
		fm.pagination_next ??= null;
	}
	return fm;
}
